        if attempt.payment_id in used_payments:
            attempt.payment_id = None
        elif attempt.payment_id:
            used_payments.add(attempt.payment_id)
            attempt.invoice_id = attempt.payment.invoice_id
            attempt.amount = attempt.payment.amount
            attempt.currency = attempt.payment.currency
        attempt.status = {'created': 'pending', 'succeeded': 'settled'}.get(attempt.status, attempt.status)
        if attempt.status == 'settled': attempt.settled_at = attempt.updated_at
        if attempt.status == 'failed': attempt.failed_at = attempt.updated_at
        if attempt.status == 'expired': attempt.expired_at = attempt.updated_at
        attempt.save(update_fields=('payment', 'invoice', 'amount', 'currency', 'status', 'settled_at', 'failed_at', 'expired_at'))


